window.SAOContentTranslations.registerEquipmentEntry = function registerEquipmentEntry(entry, slugify, options) {
	const id = entry.id || slugify(entry.name);
	const fields = options?.fields ? new Set(options.fields) : null;
	const includes = field => !fields || fields.has(field);
	const register = (field, value, translator = "terms") => {
		if (!value) return;
		const key = `equipment.${id}.${field}`;
		const curated = curatedProseTranslations[value];
		const spanish = curated ? curated[0] : translator === "terms"
			? translateEquipmentTermValue(window.SAOContentTranslations.translateEquivalentProse(value, "es"), 0)
			: window.SAOContentTranslations.translateEquivalentProse(value, "es");
		const french = curated ? curated[1] : translator === "terms"
			? translateEquipmentTermValue(window.SAOContentTranslations.translateEquivalentProse(value, "fr"), 1)
			: window.SAOContentTranslations.translateEquivalentProse(value, "fr");
		window.SAOContentTranslations.register(key, value,
			window.SAOContentTranslations.es[key] || spanish,
			window.SAOContentTranslations.fr[key] || french);
	};

	if (includes("name")) register("name", entry.name);
	if (includes("description")) register("description", entry.description, "prose");
	if (includes("craftingLocation")) register("craftingLocation", entry.craftingLocation);
	if (includes("craftingNote")) register("craftingNote", entry.craftingNote, "prose");
	if (includes("stats")) Object.keys(entry.stats || {}).forEach(stat => register(`stat.${slugify(stat)}`, stat));
	if (includes("craftingResources")) (entry.craftingResources || []).forEach(resource => register(`resource.${slugify(resource.item)}`, resource.item));
};

window.SAOContentTranslations.registerQuestEntry = function registerQuestEntry(entry, slugify) {
	const id = entry.id || slugify([entry.npcName, entry.city, entry.coordinates, entry.questName].join("-"));
	["npcName", "city", "questName"].forEach(field => {
		if (!entry[field]) return;
		const curated = field === "questName" ? curatedQuestTranslations[entry[field]] : null;
		const location = locationTranslations[entry[field]];
		const npc = npcTranslations[entry[field]];
		const equivalent = window.SAOContentTranslations.translateEquivalentLabel(entry[field], 0);
		const equivalentFrench = window.SAOContentTranslations.translateEquivalentLabel(entry[field], 1);
		const label = window.SAOContentTranslations.translateEquivalentLabel(entry[field], 0);
		const frenchLabel = window.SAOContentTranslations.translateEquivalentLabel(entry[field], 1);
		window.SAOContentTranslations.register(`quest.${id}.${field}`, entry[field], curated?.[0] === entry[field] ? label : curated?.[0] || location?.[0] || npc?.[0] || label, curated?.[1] === entry[field] ? frenchLabel : curated?.[1] || location?.[1] || npc?.[1] || frenchLabel);
	});
	["requirements", "bonusItems"].forEach(field => {
		if (!entry[field]) return;
		const curated = curatedQuestFieldTranslations[entry[field]];
		window.SAOContentTranslations.register(
			`quest.${id}.${field}`,
			entry[field],
			window.SAOContentTranslations.es[`quest.${id}.${field}`] || curated?.[0] || window.SAOContentTranslations.translateKnownTerms(entry[field], "es"),
			window.SAOContentTranslations.fr[`quest.${id}.${field}`] || curated?.[1] || window.SAOContentTranslations.translateKnownTerms(entry[field], "fr")
		);
	});
};

