window.SAOContentTranslations.registerMapMarker = function registerMapMarker(id, marker) {
	["title", "type", "description"].forEach(field => {
		if (!marker[field]) return;
		const key = `map.${id}.${field}`;
		const curated = field === "description" ? curatedProseTranslations[marker[field]] : null;
		const typeTranslation = field === "type" ? mapTypeTranslations[marker[field]] : null;
		const titleTranslation = field === "title" ? curatedQuestTranslations[marker[field]] || mapTitleTranslations[marker[field]] || locationTranslations[marker[field]] : null;
		const manualTitleSpanish = field === "title" ? window.SAOContentTranslations.translateEquivalentLabel(marker[field], 0) : marker[field];
		const manualTitleFrench = field === "title" ? window.SAOContentTranslations.translateEquivalentLabel(marker[field], 1) : marker[field];
		const spanish = manualTitleSpanish !== marker[field] ? manualTitleSpanish : window.SAOContentTranslations.es[key] || curated?.[0] || typeTranslation?.[0] || titleTranslation?.[0] || (field === "description" ? window.SAOContentTranslations.translateEquivalentProse(marker[field], "es") : field === "title" ? window.SAOContentTranslations.translateEquivalentLabel(translateEquipmentTermValue(marker[field], 0), 0) : window.SAOContentTranslations.translateEquivalentLabel(marker[field], 0));
		const french = manualTitleFrench !== marker[field] ? manualTitleFrench : window.SAOContentTranslations.fr[key] || curated?.[1] || typeTranslation?.[1] || titleTranslation?.[1] || (field === "description" ? window.SAOContentTranslations.translateEquivalentProse(marker[field], "fr") : field === "title" ? window.SAOContentTranslations.translateEquivalentLabel(translateEquipmentTermValue(marker[field], 1), 1) : window.SAOContentTranslations.translateEquivalentLabel(marker[field], 1));
		window.SAOContentTranslations.register(key, marker[field], spanish, french);
	});
};

